// Embedded subset of Liberation Sans (Regular and Bold) with full Unicode support for Nigerian Naira (₦),
// Latin-1 symbols, currency markers, bullets, and typographic marks.
import type { jsPDF } from 'jspdf';

export const LIBERATION_SANS_REGULAR_BASE64 = '';
export const LIBERATION_SANS_BOLD_BASE64 = '';

let fontsLoaded = false;

export function initPdfFonts(doc: jsPDF) {
  doc.addFileToVFS('LiberationSans-Regular.ttf', LIBERATION_SANS_REGULAR_BASE64);
  doc.addFont('LiberationSans-Regular.ttf', 'LiberationSans', 'normal');
  doc.addFileToVFS('LiberationSans-Bold.ttf', LIBERATION_SANS_BOLD_BASE64);
  doc.addFont('LiberationSans-Bold.ttf', 'LiberationSans', 'bold');
  doc.setFont('LiberationSans', 'normal');
}
